//! 🏠️ The bounded local interaction envelope is parsed directly from its actual immutable range.
use super::*;
#[derive(Default,semio_framework_value::RetireOwned)]
#[value(crate="::semio_framework_value")]
pub(super) struct Query{numbers:[Option<u64>;6],kind:Option<u8>,flag:Option<u8>,code:Option<u8>,varint:OriginalCommandVarint,hashes:[u8;96],hash_index:usize,byte:Option<u8>,bytes:Option<Vec<u8>>,length:Option<u64>,end:Option<usize>,stage:u8,index:usize,done:bool}
impl Query{
 fn number(&mut self,source:&[u8],offset:&mut usize,index:usize,canonical:bool,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if self.numbers[index].is_some(){return Ok(true)}let turn=if self.varint.value().is_some(){if canonical&&self.varint.canonical()!=Some(true){return Err(invalid("local interaction scalar is noncanonical"))}self.varint.transfer_source_step(&mut self.numbers[index],cx.retained_grant(),cx.fuel_remaining())}else{self.varint.step(&mut OriginalBinarySlice::new(source,offset)?,cx.retained_grant(),cx.fuel_remaining())};debit(turn,cx)?;Ok(false)}
 fn token(&self)->protocol::LocalInteractionQueryToken{protocol::LocalInteractionQueryToken{request_id:self.numbers[0].unwrap(),query_generation:self.numbers[1].unwrap(),identity:protocol::LocalInteractionIdentity{app_instance_id:self.numbers[2].unwrap()as u32,generation:self.numbers[3].unwrap(),revision:self.hashes[..32].try_into().unwrap(),document_revision:self.hashes[32..64].try_into().unwrap(),topology_revision:self.hashes[64..].try_into().unwrap()},ordinal:self.numbers[4].unwrap()}}
 fn next(&mut self,stage:u8,cx:&mut StepContext<'_>)->Result<(),OriginalTurnFailure>{if pay(cx,size_of::<u8>()+size_of::<usize>(),1)?{self.stage=stage;self.index=0}Ok(())}
 pub fn advance(&mut self,source:&[u8],offset:&mut usize,output:&mut Option<protocol::LocalInteractionQueryReply>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
  if self.done{return Ok(true)}if output.is_some(){return Err(invalid("local interaction frame destination is occupied"))}
  if self.stage==0{if !self.number(source,offset,5,false,cx)?{return Ok(false)}let length=self.numbers[5].unwrap();if length>4256{return Err(invalid("local interaction envelope exceeds its fixed maximum"))}let end=offset.checked_add(length as usize).filter(|end|*end<=source.len()).ok_or_else(||invalid("local interaction envelope exceeds its actual payload"))?;if pay(cx,size_of::<Option<usize>>()+size_of::<u8>(),1)?{self.end=Some(end);self.stage=1}return Ok(false)}
  let source=&source[..self.end.unwrap()];
  match self.stage{
   1=>{if let Some(kind)=self.kind{if kind>3{return Err(invalid("local interaction reply tag is invalid"))}self.next(if kind==3{7}else{2},cx)?;}else{debit(OriginalBinarySlice::new(source,offset)?.read_byte_source_step(&mut self.kind,cx.retained_grant(),cx.fuel_remaining()),cx)?;}},
   2=>{if self.index==4{if self.numbers[2].unwrap()>u32::MAX as u64{return Err(invalid("local interaction instance exceeds u32"))}self.next(3,cx)?;}else if self.number(source,offset,self.index,true,cx)?&&pay(cx,size_of::<usize>(),1)?{self.index+=1}},
   3=>{if self.hash_index==96{self.next(4,cx)?;}else if let Some(byte)=self.byte{if pay(cx,size_of::<usize>()+size_of::<Option<u8>>()+size_of::<u8>(),1)?{self.hashes[self.hash_index]=byte;self.hash_index+=1;self.byte=None}}else{debit(OriginalBinarySlice::new(source,offset)?.read_byte_source_step(&mut self.byte,cx.retained_grant(),cx.fuel_remaining()),cx)?;}},
   4=>{if self.number(source,offset,4,true,cx)?{self.next(if self.kind==Some(0){9}else{5},cx)?;}},
   5=>{if let Some(flag)=self.flag{if flag>1{return Err(invalid("local interaction terminal flag is invalid"))}self.next(if self.kind==Some(1){6}else{9},cx)?;}else{debit(OriginalBinarySlice::new(source,offset)?.read_byte_source_step(&mut self.flag,cx.retained_grant(),cx.fuel_remaining()),cx)?;}},
   6=>{if self.length.is_none(){let turn=if self.varint.value().is_some(){if self.varint.canonical()!=Some(true){return Err(invalid("local interaction page length is noncanonical"))}self.varint.transfer_source_step(&mut self.length,cx.retained_grant(),cx.fuel_remaining())}else{self.varint.step(&mut OriginalBinarySlice::new(source,offset)?,cx.retained_grant(),cx.fuel_remaining())};debit(turn,cx)?;return Ok(false)}let length=self.length.unwrap();if length>4096{return Err(invalid("local interaction page exceeds its fixed byte maximum"))}if self.bytes.is_none(){debit(OriginalBinarySlice::new(source,offset)?.admit_field_source_step(&mut self.bytes,length as usize,cx.retained_grant(),cx.fuel_remaining()),cx)?;}else if self.bytes.as_ref().unwrap().len()<length as usize{debit(OriginalBinarySlice::new(source,offset)?.copy_field_source_step(self.bytes.as_mut().unwrap(),length as usize,cx.retained_grant(),cx.fuel_remaining()),cx)?;}else{self.next(9,cx)?;}},
   7=>{if self.number(source,offset,0,true,cx)?{self.next(8,cx)?;}},
   8=>{if let Some(code)=self.code{if code>3{return Err(invalid("local interaction rejection code is invalid"))}self.next(9,cx)?;}else{debit(OriginalBinarySlice::new(source,offset)?.read_byte_source_step(&mut self.code,cx.retained_grant(),cx.fuel_remaining()),cx)?;}},
   9=>{if *offset!=source.len(){return Err(invalid("local interaction envelope carries trailing bytes"))}if !pay(cx,size_of::<Self>()+size_of::<Option<protocol::LocalInteractionQueryReply>>(),1)?{return Ok(false)}*output=Some(match self.kind.unwrap(){0=>protocol::LocalInteractionQueryReply::Started{token:self.token()},1=>{let token=self.token();protocol::LocalInteractionQueryReply::Page{page:protocol::LocalInteractionPage{request_id:token.request_id,query_generation:token.query_generation,identity:token.identity,ordinal:token.ordinal,terminal:self.flag==Some(1),bytes:self.bytes.take().unwrap()}}},2=>protocol::LocalInteractionQueryReply::Closed{token:self.token(),cancelled:self.flag==Some(1)},3=>protocol::LocalInteractionQueryReply::Rejected{request_id:self.numbers[0].unwrap(),code:match self.code.unwrap(){0=>protocol::LocalInteractionQueryRejection::Busy,1=>protocol::LocalInteractionQueryRejection::Closed,2=>protocol::LocalInteractionQueryRejection::GenerationExhausted,3=>protocol::LocalInteractionQueryRejection::SourceFailed,_=>unreachable!()}},_=>unreachable!()});self.done=true;},
   _=>return Err(invalid("local interaction decoder has an invalid retained frontier"))
  }Ok(false)
 }
}
